<template>
<div><p v-if="loading">Loading agreement…</p><p v-else-if="error" class="error">{{ error }}</p><template v-else>
<RouterLink :to="`/organizations/${agreement.organization}`">← Back to Organization</RouterLink>
<div class="page-heading heading-actions"><div><h1>{{ agreement.title }}</h1><p>{{ typeLabel }} · <span class="status-badge">{{ statusLabel }}</span></p></div><ActionMenu @edit="openAgreementEdit" @delete="askDelete('agreement', agreement)" /></div>
<div class="detail-card agreement-meta"><p><strong>Organization:</strong> {{ organizationName }}</p><p><strong>Signed date:</strong> {{ agreement.signed_date || '—' }}</p><p><strong>Start date:</strong> {{ agreement.start_date || '—' }}</p><p><strong>Expiration date:</strong> {{ agreement.expiration_date || '—' }}</p></div><h2>Overview</h2><div class="detail-card">{{ agreement.description || 'No description recorded.' }}</div>
<section><div class="section-heading"><h2>Contacts</h2><button class="primary small-button" @click="contactForm=!contactForm">+ Add Contact</button></div><form v-if="contactForm" class="detail-card simple-form" @submit.prevent="createContact"><label>Side<select v-model="contact.side"><option value="OUR_SIDE">Our side</option><option value="PARTNER_SIDE">Partner side</option></select></label><label>Full name<input v-model="contact.full_name" required></label><label>Position<input v-model="contact.position"></label><label>Email<input v-model="contact.email" type="email"></label><label>Phone<input v-model="contact.phone"></label><label>Role<input v-model="contact.role"></label><label class="checkbox"><input v-model="contact.is_primary" type="checkbox"> Primary</label><div><button class="primary" :disabled="saving">{{saving?'Saving…':'Save Contact'}}</button><p v-if="formError" class="error">{{formError}}</p></div></form><div v-if="contacts.length" class="contact-groups"><div v-for="group in contactGroups" :key="group.label"><h3>{{group.label}}</h3><div v-if="group.items.length" class="detail-card contact-list"><div v-for="item in group.items" :key="item.id" class="contact-row"><div><strong>{{item.contact_name}}</strong><small>{{item.contact_position||'—'}}</small></div><span>{{item.contact_email||'—'}}</span><span>{{item.contact_phone||'—'}}</span><span>{{item.role||'—'}}<small v-if="item.is_primary"> · Primary</small></span><ActionMenu @edit="openContactEdit(item)" @delete="askDelete('contact',item)" /></div></div><p v-else class="empty">No contacts recorded.</p></div></div><p v-else class="empty">No contacts recorded.</p></section>
<section><div class="section-heading"><h2>Documents</h2><button class="primary small-button" @click="documentForm=!documentForm">+ Upload Document</button></div><form v-if="documentForm" class="detail-card simple-form" @submit.prevent="uploadDocument"><label>Title<input v-model="document.title" required></label><label>Document type<input v-model="document.document_type"></label><label>File<input type="file" required @change="document.file=$event.target.files[0]"></label><label>Description<textarea v-model="document.description"></textarea></label><div><button class="primary" :disabled="saving">{{saving?'Uploading…':'Upload Document'}}</button><p v-if="formError" class="error">{{formError}}</p></div></form><div v-if="documents.length" class="detail-card"><div v-for="item in documents" :key="item.id" class="list-row"><strong>{{item.title}}</strong><span>{{item.document_type||'—'}}</span><span>{{formatDate(item.uploaded_at)}}</span><a :href="item.file" target="_blank" rel="noopener">Open file</a><ActionMenu @edit="openDocumentEdit(item)" @delete="askDelete('document',item)" /></div></div><p v-else class="empty">No documents recorded.</p></section>
<section><div class="section-heading"><h2>Activities</h2><button class="primary small-button" @click="activityForm=!activityForm">+ Add Activity</button></div><form v-if="activityForm" class="detail-card simple-form" @submit.prevent="createActivity"><label>Activity type<select v-model="activity.activity_type"><option v-for="(label,value) in ACTIVITY_TYPE_LABELS" :key="value" :value="value">{{label}}</option></select></label><label>Title<input v-model="activity.title"></label><label>Date<input v-model="activity.activity_date" type="datetime-local" required></label><label>Description<textarea v-model="activity.description"></textarea></label><div><button class="primary" :disabled="saving">{{saving?'Saving…':'Save Activity'}}</button><p v-if="formError" class="error">{{formError}}</p></div></form><div v-if="activities.length" class="detail-card"><div v-for="item in sortedActivities" :key="item.id" class="list-row activity"><strong>{{formatDate(item.activity_date)}}</strong><span>{{activityType(item.activity_type)}}</span><span>{{item.title||'—'}}</span><p v-if="item.description">{{item.description}}</p><ActionMenu @edit="openActivityEdit(item)" @delete="askDelete('activity',item)" /></div></div><p v-else class="empty">No activities recorded.</p></section>
<ConfirmDialog :open="!!pendingDelete" :busy="saving" :title="pendingDelete?.kind==='agreement'?'Delete agreement?':`Delete ${pendingDelete?.kind==='contact'?'contact relation':pendingDelete?.kind||'record'}?`" :message="pendingDelete?.kind==='agreement'?'This will also remove related agreement contacts, documents, and activities.':undefined" @cancel="pendingDelete=null" @confirm="deletePending" />
<div v-if="editKind" class="modal-backdrop"><form class="modal simple-form" @submit.prevent="saveEdit"><h2>Edit {{editKind}}</h2><template v-if="editKind==='agreement'"><label>Title<input v-model="editData.title" required></label><label>Type<select v-model="editData.agreement_type"><option v-for="(label,value) in AGREEMENT_TYPE_LABELS" :key="value" :value="value">{{label}}</option></select></label><label>Status<select v-model="editData.status"><option v-for="(label,value) in AGREEMENT_STATUS_LABELS" :key="value" :value="value">{{label}}</option></select></label><label>Description<textarea v-model="editData.description"></textarea></label><label>Signed date<input v-model="editData.signed_date" type="date"></label><label>Start date<input v-model="editData.start_date" type="date"></label><label>Expiration date<input v-model="editData.expiration_date" type="date"></label></template><template v-if="editKind==='contact'"><label>Full name<input v-model="editData.full_name" required></label><label>Position<input v-model="editData.position"></label><label>Email<input v-model="editData.email"></label><label>Phone<input v-model="editData.phone"></label><label>Side<select v-model="editData.side"><option value="OUR_SIDE">Our side</option><option value="PARTNER_SIDE">Partner side</option></select></label><label>Role<input v-model="editData.role"></label><label class="checkbox"><input type="checkbox" v-model="editData.is_primary"> Primary</label></template><template v-if="editKind==='document'"><label>Title<input v-model="editData.title" required></label><label>Document type<input v-model="editData.document_type"></label><label>Description<textarea v-model="editData.description"></textarea></label></template><template v-if="editKind==='activity'"><label>Activity type<select v-model="editData.activity_type"><option v-for="(label,value) in ACTIVITY_TYPE_LABELS" :key="value" :value="value">{{label}}</option></select></label><label>Title<input v-model="editData.title"></label><label>Date<input v-model="editData.activity_date" type="datetime-local" required></label><label>Description<textarea v-model="editData.description"></textarea></label></template><p v-if="formError" class="error">{{formError}}</p><div class="modal-actions"><button type="button" @click="editKind=''">Cancel</button><button class="primary" :disabled="saving">{{saving?'Saving…':'Save'}}</button></div></form></div>
</template></div></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import client from '../api/client';import ActionMenu from '../components/ActionMenu.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import {AGREEMENT_TYPE_LABELS,AGREEMENT_STATUS_LABELS,ACTIVITY_TYPE_LABELS} from '../constants/partnerships';const route=useRoute(),router=useRouter(),agreement=ref(null),contacts=ref([]),documents=ref([]),activities=ref([]),loading=ref(true),error=ref(''),saving=ref(false),formError=ref(''),contactForm=ref(false),documentForm=ref(false),activityForm=ref(false),editKind=ref(''),editData=ref({}),pendingDelete=ref(null);const blankContact=()=>({side:'OUR_SIDE',full_name:'',position:'',email:'',phone:'',role:'',is_primary:false}),blankDocument=()=>({title:'',document_type:'',file:null,description:''}),blankActivity=()=>({activity_type:'NOTE',title:'',activity_date:'',description:''});const contact=ref(blankContact()),document=ref(blankDocument()),activity=ref(blankActivity());const typeLabel=computed(()=>AGREEMENT_TYPE_LABELS[agreement.value?.agreement_type]||agreement.value?.agreement_type),statusLabel=computed(()=>AGREEMENT_STATUS_LABELS[agreement.value?.status]||agreement.value?.status),organizationName=computed(()=>agreement.value?.organization_name||agreement.value?.organization),contactGroups=computed(()=>[{label:'Our side',items:contacts.value.filter(c=>c.side==='OUR_SIDE')},{label:'Partner side',items:contacts.value.filter(c=>c.side==='PARTNER_SIDE')}]),sortedActivities=computed(()=>[...activities.value].sort((a,b)=>new Date(b.activity_date)-new Date(a.activity_date)));const formatDate=v=>v?new Date(v).toLocaleString():'—',activityType=v=>ACTIVITY_TYPE_LABELS[v]||v,list=r=>Array.isArray(r.data)?r.data:r.data.results||[],denied=e=>e.response?.status===403?'You do not have permission to perform this action.':(e.response?.data?.detail||Object.values(e.response?.data||{}).flat().join(' ')||'Unable to save.');async function loadContacts(){contacts.value=list(await client.get('/api/agreement-contacts/',{params:{agreement:route.params.id}}))}async function loadDocuments(){documents.value=list(await client.get('/api/documents/',{params:{agreement:route.params.id}}))}async function loadActivities(){activities.value=list(await client.get('/api/activities/',{params:{agreement:route.params.id}}))}async function write(fn){if(saving.value)return;saving.value=true;formError.value='';try{await fn()}catch(e){formError.value=denied(e)}finally{saving.value=false}}async function createContact(){await write(async()=>{const c=await client.post('/api/contacts/',{full_name:contact.value.full_name,position:contact.value.position,email:contact.value.email,phone:contact.value.phone});await client.post('/api/agreement-contacts/',{agreement:route.params.id,contact:c.data.id,...contact.value});contact.value=blankContact();contactForm.value=false;await loadContacts()})}async function uploadDocument(){await write(async()=>{const d=new FormData();Object.entries(document.value).forEach(([k,v])=>{if(v!==null)d.append(k,v)});d.append('agreement',route.params.id);await client.post('/api/documents/',d);document.value=blankDocument();documentForm.value=false;await loadDocuments()})}async function createActivity(){await write(async()=>{await client.post('/api/activities/',{...activity.value,agreement:route.params.id});activity.value=blankActivity();activityForm.value=false;await loadActivities()})}function openAgreementEdit(){editKind.value='agreement';editData.value={...agreement.value}}function openContactEdit(x){editKind.value='contact';editData.value={...x,full_name:x.contact_name,position:x.contact_position,email:x.contact_email,phone:x.contact_phone}}function openDocumentEdit(x){editKind.value='document';editData.value={...x}}function openActivityEdit(x){editKind.value='activity';editData.value={...x,activity_date:x.activity_date?.slice(0,16)}}async function saveEdit(){await write(async()=>{const d=editData.value;if(editKind.value==='agreement'){const r=await client.patch(`/api/agreements/${agreement.value.id}/`,d);agreement.value=r.data}else if(editKind.value==='contact'){await client.patch(`/api/contacts/${d.contact}/`,{full_name:d.full_name,position:d.position,email:d.email,phone:d.phone});await client.patch(`/api/agreement-contacts/${d.id}/`,{side:d.side,role:d.role,is_primary:d.is_primary});await loadContacts()}else if(editKind.value==='document'){await client.patch(`/api/documents/${d.id}/`,{title:d.title,document_type:d.document_type,description:d.description});await loadDocuments()}else{await client.patch(`/api/activities/${d.id}/`,{activity_type:d.activity_type,title:d.title,activity_date:d.activity_date,description:d.description});await loadActivities()}editKind.value=''})}function askDelete(kind,item){pendingDelete.value={kind,item}}async function deletePending(){const p=pendingDelete.value;if(!p)return;await write(async()=>{if(p.kind==='agreement'){await client.delete(`/api/agreements/${p.item.id}/`);pendingDelete.value=null;await router.push(`/organizations/${p.item.organization}`);return}if(p.kind==='contact')await client.delete(`/api/agreement-contacts/${p.item.id}/`);else await client.delete(`/api/${p.kind==='document'?'documents':'activities'}/${p.item.id}/`);pendingDelete.value=null;if(p.kind==='contact')await loadContacts();else if(p.kind==='document')await loadDocuments();else await loadActivities()})}onMounted(async()=>{try{const id=route.params.id;const r=await Promise.all([client.get(`/api/agreements/${id}/`),loadContacts(),loadDocuments(),loadActivities()]);agreement.value=r[0].data}catch(e){error.value=e.response?.status===404?'Agreement not found.':'Unable to load agreement.'}finally{loading.value=false}})
</script>
